// RestJokes returns the rest-pause joke list in language l (English fallback).
func RestJokes(l Lang) []string {
	col := 1
	if l == RU {
		col = 0
	}
	out := make([]string, len(restJokes))
	for i, row := range restJokes {
		s := row[col]
		if s == "" {
			s = row[1]
		}
		out[i] = s
	}
	return out
}
